insert into programmes (id, slug, nom, surtitre_hero, h1_variable, description_hero, cta_hero, description_programme, description_carte, couleur, statut, seo_mot_cle_principal, seo_title, seo_meta_description, seo_og_title, seo_og_description, seo_og_image, seo_canonical, seo_indexable) values
  ('prg-social-media', 'social-media', 'Social Média', 'Programme Social Média', 'Restez dans la course.', 'Choisissez parmi {modules} de 60 minutes pour renforcer des compétences précises en stratégie, contenu et plateformes Social Media. Accès à vie et sessions de coaching collectif.', 'Découvrir le programme Social Média', 'Des modules indépendants conçus pour les Social Media Managers, Community Managers et professionnels de la communication qui souhaitent actualiser leurs pratiques et renforcer des compétences ciblées.', 'Pour les professionnels du Social Media et de la communication qui souhaitent actualiser leurs pratiques et renforcer des compétences précises.', '#80368D', 'publie', 'formation social média Abidjan', 'Programme Social Média | E-Masterclass Big Five', '{modules} de 60 minutes pour renforcer des compétences précises en stratégie, contenu et plateformes Social Media. 10 000 FCFA TTC par module, accès à vie.', null, null, null, null, true),
  ('prg-entrepreneurs', 'entrepreneurs', 'Entrepreneurs', 'Programme Entrepreneurs', 'Soyez à jour.', 'Choisissez parmi {modules} de 60 minutes pour renforcer les compétences utiles au développement de votre activité : valider une idée, fixer vos prix, vendre et gagner en visibilité.', 'Découvrir le programme Entrepreneurs', 'Des modules indépendants conçus pour les entrepreneurs en activité ou en lancement qui souhaitent renforcer des compétences pratiques et faire évoluer leur activité.', 'Pour les entrepreneurs en activité ou en lancement qui souhaitent renforcer les compétences utiles au développement de leur activité.', '#29358B', 'publie', 'formation entrepreneur Côte d’Ivoire', 'Programme Entrepreneurs | E-Masterclass Big Five', '{modules} de 60 minutes pour valider une idée, fixer ses prix, vendre et gagner en visibilité. 10 000 FCFA TTC par module, accès à vie.', null, null, null, null, true);
