insert into formateurs (id, slug, nom, expertise, bio, programme_principal, photo, fiche_complete, position, coaching_prive_fcfa_heure, coaching_prive_actif, seo_mot_cle_principal, seo_title, seo_meta_description, seo_og_title, seo_og_description, seo_og_image, seo_canonical, seo_indexable) values
  ('for-declercq', 'jeremie-de-clercq', 'Jérémie De Clercq', 'Stratégie business & entrepreneuriat', 'Jérémie De Clercq intervient sur les modules consacrés à la structuration des fondamentaux d’une activité : modèle économique, coûts, prix et lecture du marché. Il accompagne des entrepreneurs et des équipes marketing en Afrique francophone.', 'entrepreneurs', '/images/formateurs/jeremie-de-clercq.svg', true, 0, 50000, false, null, null, null, null, null, null, null, true),
  ('for-othniel', 'coury-othniel', 'Coury Othniel', 'Copywriting & contenu', 'Copywriter spécialisé dans les contenus qui retiennent l’attention sur les réseaux sociaux en Afrique francophone. Il anime les modules de rédaction persuasive des deux programmes.', 'social-media', '/images/formateurs/coury-othniel.svg', true, 1, 50000, true, null, null, null, null, null, null, null, true),
  ('for-waffo', 'kevine-waffo', 'Kevine Waffo', 'Stratégie social media & ciblage', 'Kevine Waffo construit des plans d’action social media pour des marques et des institutions : diagnostic, ciblage, planning éditorial et pilotage des publications.', 'social-media', '/images/formateurs/kevine-waffo.svg', true, 2, 50000, true, null, null, null, null, null, null, null, true),
  ('for-cocou', 'emmanuel-cocou', 'Emmanuel Cocou', 'Offres & positionnement', 'Emmanuel Cocou aide les entrepreneurs à transformer une compétence en offre lisible : périmètre, promesse, livrables et argumentaire de vente.', 'entrepreneurs', '/images/formateurs/emmanuel-cocou.svg', true, 3, 50000, false, null, null, null, null, null, null, null, true),
  ('for-nontondji', 'maurice-nontondji', 'Maurice Nontondji', 'LinkedIn : algorithme & prospection', 'Maurice Nontondji travaille la visibilité professionnelle sur LinkedIn : compréhension de l’algorithme, formats de publication et prospection directe.', 'social-media', '/images/formateurs/maurice-nontondji.svg', true, 4, 50000, false, null, null, null, null, null, null, null, true),
  ('for-soboro', 'lyle-soboro', 'Lyle Soboro', 'Vente, TikTok & acquisition client', 'Lyle Soboro accompagne des vendeurs et des commerces dans l’acquisition client sans site web : WhatsApp Business, TikTok et tunnels de vente simples.', 'entrepreneurs', '/images/formateurs/lyle-soboro.svg', true, 5, 50000, true, null, null, null, null, null, null, null, true),
  ('for-akinocho', 'nouroudine-akinocho', 'Nouroudine Akinocho', 'Visibilité & croissance en ligne', 'Nouroudine Akinocho intervient sur la visibilité en ligne des petites structures : référencement local, présence sur les plateformes et croissance organique.', 'entrepreneurs', '/images/formateurs/nouroudine-akinocho.svg', true, 6, 50000, false, null, null, null, null, null, null, null, true);
insert into modules (id, slug, numero, titre, programme, thematique_id, formateur_id, promesse, pourquoi, pour_qui, prerequis, acquis, livrable, faq, duree_minutes, prix_fcfa, statut, publie_le, date_lancement, prix_masque, points_forts, image, image_alt, pret_le, seo_mot_cle_principal, seo_title, seo_meta_description, seo_og_title, seo_og_description, seo_og_image, seo_canonical, seo_indexable) values
  ('mod-plan-daction-social-media-strategie-et-ciblage', 'plan-daction-social-media-strategie-et-ciblage', 2, 'Plan d’action social media : Stratégie & Ciblage', 'social-media', 'th-sm-fondations', 'for-waffo', 'Construisez un plan d’action social media qui part d’une cible précise plutôt que d’une intuition.', 'Publier pour « tout le monde » revient à ne parler à personne. Ce module structure le diagnostic, le choix de la cible et les axes stratégiques qui en découlent, avec des arbitrages assumés.', array['Vous démarrez sur un nouveau compte ou une nouvelle marque.', 'Vos publications touchent une audience trop large ou mal qualifiée.', 'Vous devez présenter une stratégie à un décideur.']::text[], 'Aucun prérequis particulier.', array['poser un diagnostic factuel en cinq analyses ;', 'fixer des objectifs mesurables de notoriété, d’engagement, de conversion et de fidélisation ;', 'choisir ses plateformes, ses piliers éditoriaux et son ton ;', 'déployer des tactiques concrètes et arbitrer organique contre payant.']::text[], 'Un plan d’action social media sur une page, prêt à être présenté.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-plan-daction-social-media-planning-editorial', 'plan-daction-social-media-planning-editorial', 3, 'Plan d’action social media : Planning éditorial', 'social-media', 'th-sm-fondations', 'for-waffo', 'Transformez une stratégie en planning tenable, avec des formats et un rythme que vous pourrez réellement soutenir.', 'La régularité échoue rarement par manque d’idées : elle échoue par manque de système. Ce module installe un planning éditorial calibré sur vos moyens réels de production.', array['Vous publiez de façon irrégulière.', 'Vous manquez d’idées en fin de mois.', 'Vous travaillez seul ou avec une petite équipe.']::text[], 'Avoir défini une cible et des axes stratégiques.', array['poser la stratégie qui structure son calendrier éditorial ;', 'construire un calendrier sur trente jours ;', 'présenter son plan à un décideur.']::text[], 'Un calendrier éditorial de trente jours et la trame pour le présenter à un décideur.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-formules-de-redaction-persuasive', 'formules-de-redaction-persuasive', 4, 'Formules de rédaction persuasive & adapt. plateforme', 'social-media', 'th-sm-copywriting', 'for-othniel', 'Appliquez des structures de rédaction éprouvées pour écrire plus vite des messages qui portent.', 'Devant une page blanche, la qualité dépend du temps disponible. Les formules de rédaction suppriment cette dépendance : elles donnent une ossature au message et libèrent l’attention pour le fond.', array['Vous écrivez régulièrement pour les réseaux sociaux.', 'Vos textes manquent de structure ou de chute.', 'Vous voulez réduire votre temps de rédaction.']::text[], 'Aucun prérequis particulier.', array['appuyer un message sur les ressorts de la persuasion ;', 'adapter un même contenu au format de chaque plateforme ;', 'appliquer les formules de rédaction incontournables.']::text[], 'Un carnet de formules annotées et adaptées à votre activité.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-accroches-qui-stoppent-le-scroll-et-ia-copywriting', 'accroches-qui-stoppent-le-scroll-et-ia-copywriting', 5, 'Accroches qui stoppent le scroll & IA dans le copywriting', 'social-media', 'th-sm-copywriting', 'for-othniel', 'Apprenez à construire plus rapidement des accroches capables de retenir l’attention, avec une méthode claire et l’IA comme assistant.', '<p><strong>Une publication</strong> peut être utile, bien conçue et correctement ciblée sans retenir l’attention si son ouverture manque d’impact. Ce module vous aide à structurer vos premiers mots, varier vos angles et produire plus rapidement sans déléguer votre réflexion à l’IA.</p>', array['Vous gérez les réseaux sociaux d’une marque ou de plusieurs clients.', 'Vos contenus peinent à retenir l’attention.', 'Vous souhaitez produire plus rapidement sans sacrifier la qualité.']::text[], 'Aucun prérequis particulier. La méthode est expliquée et appliquée progressivement pendant le module.', array['comprendre le rôle d’une accroche et la distinguer du clickbait ;', 'appliquer la formule d’une accroche efficace et soigner la première ligne visible ;', 'rédiger vos prompts avec la méthode CRAFT et itérer avec l’IA ;', 'connaître les limites de l’IA et réécrire ses propositions ;', 'choisir les indicateurs à suivre selon votre objectif.']::text[], 'Vos propres accroches adaptées à votre secteur, travaillées dans les deux exercices du module, et une méthode de prompt réutilisable avec l’IA.', '[{"question":"Ai-je besoin d’un outil d’IA payant ?","reponse":"Non. Le module ne dépend pas d’un outil payant particulier. Les fonctionnalités nécessaires et les différentes options sont présentées pendant le module."},{"question":"La méthode peut-elle s’appliquer à tous les secteurs ?","reponse":"Oui. Les principes enseignés sont adaptables à différents secteurs. Les exercices vous permettent de travailler directement à partir de votre activité, de votre marque ou de vos clients."},{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-creer-un-buzz-sur-les-reseaux-sociaux', 'creer-un-buzz-sur-les-reseaux-sociaux', 6, 'Créer un buzz sur les réseaux sociaux', 'social-media', 'th-sm-copywriting', 'for-othniel', 'Comprenez ce qui déclenche réellement la circulation d’un contenu, et ce qu’il est raisonnable d’en attendre.', 'Le buzz n’est pas un objectif de communication : c’est une conséquence. Ce module démonte les mécaniques de diffusion et distingue ce qui se pilote de ce qui relève du hasard.', array['Vous travaillez sur une marque grand public.', 'On vous demande régulièrement « du viral ».', 'Vous souhaitez arbitrer entre visibilité et réputation.']::text[], 'Aucun prérequis particulier.', array['identifier les ressorts de diffusion ;', 'concevoir un contenu partageable ;', 'anticiper les risques de réputation.']::text[], 'Une grille d’évaluation des risques et opportunités avant publication.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'en-preparation', null, null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, false),
  ('mod-linkedin-algorithme-et-prospection', 'linkedin-algorithme-et-prospection', 7, 'LinkedIn : algorithme & prospection', 'social-media', 'th-sm-plateformes', 'for-nontondji', 'Utilisez LinkedIn comme un canal de prospection, pas seulement comme une vitrine professionnelle.', 'LinkedIn récompense des comportements précis. Ce module explique ce que la plateforme valorise, puis construit une routine de publication et de prise de contact qui tient en trente minutes par jour.', array['Vous vendez à des professionnels.', 'Votre profil reçoit peu de visites.', 'Vos prises de contact restent sans réponse.']::text[], 'Disposer d’un profil LinkedIn actif.', array['optimiser son profil ;', 'publier des formats adaptés ;', 'structurer une séquence de prise de contact.']::text[], 'Une séquence de prospection en cinq messages, prête à personnaliser.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-linkedin-algorithme-et-optimisation-du-profil', 'linkedin-algorithme-et-optimisation-du-profil', 8, 'LinkedIn : Algorithme & Optimisation du profil', 'social-media', 'th-sm-plateformes', 'for-nontondji', 'Comprenez le moteur de distribution de LinkedIn, puis réglez votre profil pour qu’il travaille en votre faveur à chaque publication.', 'Depuis 360Brew, LinkedIn ne distribue plus les publications selon les mêmes règles : le profil est lu en même temps que le post. Ce module explique la nouvelle logique de distribution, puis transforme cette compréhension en réglages concrets et en un plan d’action 48h.', array['Vous publiez sur LinkedIn sans comprendre pourquoi la portée varie.', 'Votre profil reçoit des visites qui ne débouchent sur rien.', 'Vous voulez agir vite, sans refondre toute votre présence.']::text[], 'Disposer d’un profil LinkedIn actif.', array['comprendre le moteur de distribution avant de vouloir le nourrir ;', 'régler chaque bloc du profil que l’algorithme lit avec vos posts ;', 'dérouler un plan d’action en 48h.']::text[], 'Un profil LinkedIn optimisé bloc par bloc et un plan d’action 48h.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-publicite-sociale-lancer-sa-premiere-campagne', 'publicite-sociale-lancer-sa-premiere-campagne', 9, 'Publicité sociale : lancer sa première campagne', 'social-media', 'th-sm-plateformes', 'for-soboro', 'Lancez une première campagne payante maîtrisée, avec un budget contenu et un résultat mesurable.', 'La publicité sociale amplifie ce qui fonctionne déjà et gaspille tout le reste. Ce module suit une campagne réelle du cadrage jusqu’à la lecture des résultats.', array['Vous n’avez jamais lancé de campagne payante.', 'Vos précédentes campagnes n’ont pas été mesurées.', 'Vous disposez d’un budget limité.']::text[], 'Disposer d’une page professionnelle active.', array['paramétrer une campagne complète ;', 'construire une audience pertinente ;', 'interpréter un rapport de performance.']::text[], 'Un modèle de brief de campagne et une grille de lecture des résultats.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-valider-son-idee-de-business-avant-dinvestir', 'valider-son-idee-de-business-avant-dinvestir', 1, 'Valider son idée de business avant d’investir', 'entrepreneurs', 'th-ent-fondations', 'for-declercq', 'Vérifiez qu’une idée répond à un besoin réel avant d’y engager du temps et de l’argent.', 'La majorité des projets échouent sur une hypothèse jamais vérifiée. Ce module transforme une intuition en série de tests simples, réalisables en quelques jours et sans budget.', array['Vous avez une idée que vous n’avez pas encore testée.', 'Vous hésitez à investir dans un premier stock ou un outil.', 'Vous voulez éviter de construire ce que personne n’achètera.']::text[], 'Aucun prérequis particulier.', array['formuler une hypothèse testable ;', 'concevoir un test rapide et peu coûteux ;', 'prendre une décision fondée sur des retours réels.']::text[], 'Un protocole de test complété, avec critères de décision définis à l’avance.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-fixer-le-juste-prix-de-ses-produits-et-services', 'fixer-le-juste-prix-de-ses-produits-et-services', 2, 'Fixer le juste prix de ses produits et services', 'entrepreneurs', 'th-ent-fondations', 'for-declercq', 'Apprenez à fixer un prix qui couvre vos coûts, valorise votre travail et reste cohérent avec votre marché.', 'Un prix trop faible fragilise votre marge, tandis qu’un prix mal aligné avec le marché peut freiner la vente. Ce module vous aide à sortir des décisions prises uniquement au feeling pour construire et défendre un prix fondé sur des éléments concrets.', array['Vous lancez ou gérez votre activité.', 'Vous ne connaissez pas précisément votre coût de revient.', 'Vous diminuez vos prix dès qu’un client négocie.', 'Vous souhaitez mieux défendre la valeur de votre offre.']::text[], 'Aucun prérequis particulier. Prévoyez simplement les informations disponibles sur vos coûts, vos charges et vos prix actuels.', array['calculer son coût de revient ;', 'choisir une stratégie de prix ;', 'présenter et défendre son prix avec davantage d’assurance.']::text[], 'Une grille tarifaire construite à partir des coûts réels et directement utilisable pour présenter ses prix aux clients.', '[{"question":"Dois-je déjà avoir lancé mon activité ?","reponse":"Non. Le module convient également aux porteurs de projet qui souhaitent construire leurs premiers prix sur des bases plus solides."},{"question":"Que faire si je ne connais pas encore tous mes coûts ?","reponse":"Le module vous aide à identifier les principales catégories à prendre en compte. Vous pourrez commencer avec les données disponibles, puis affiner progressivement vos calculs."},{"question":"La méthode fonctionne-t-elle pour les produits et les services ?","reponse":"Oui. Le module présente les éléments à considérer selon la nature de l’offre afin d’adapter le calcul et la stratégie de prix."},{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-structurer-une-offre-claire-qui-se-vend', 'structurer-une-offre-claire-qui-se-vend', 3, 'Structurer une offre claire qui se vend', 'entrepreneurs', 'th-ent-fondations', 'for-cocou', 'Passez d’une liste de compétences à une offre qu’un client comprend et peut acheter immédiatement.', 'Une offre floue se négocie toujours à la baisse. Ce module cadre le périmètre, le livrable, la promesse et le prix, puis construit l’argumentaire correspondant.', array['Vous proposez « un peu de tout ».', 'Vos devis donnent lieu à de longues discussions.', 'Vous souhaitez formaliser une offre reproductible.']::text[], 'Aucun prérequis particulier.', array['cadrer un périmètre ;', 'écrire une offre lisible ;', 'traiter les objections de prix.']::text[], 'Une fiche d’offre complète, prête à être envoyée à un prospect.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-trouver-ses-premiers-clients', 'construire-une-offre-simple-et-commencer-a-vendre', 4, 'Comment construire une offre simple et commencer à vendre', 'entrepreneurs', 'th-ent-vente', 'for-soboro', 'Lancez votre activité avec une offre de lancement claire et obtenez vos premières ventes sans budget, sans attendre que tout soit parfait.', 'Votre première vente ne dépend ni d’un logo, ni d’un site, ni d’un nombre d’abonnés : elle dépend d’une offre simple, présentée aux bonnes personnes. Ce module vous aide à sortir du piège de l’attente, à construire une offre de lancement qui donne envie d’acheter, puis à la vendre avec votre réseau et des canaux gratuits.', array['Vous avez un produit ou un service qui fonctionne, mais pas encore de clients réguliers.', 'Vous repoussez votre lancement en attendant d’être « prêt ».', 'Vous démarrez sans budget publicitaire.']::text[], 'Aucun prérequis particulier. Il suffit d’avoir un produit ou un service à proposer.', array['dépasser le piège de l’attente et démarrer avec ce que vous avez ;', 'construire une offre de lancement simple, à un prix accessible ;', 'rendre l’offre pressante grâce à des limites de durée, de quantité et des bonus ;', 'activer votre réseau sans le braquer, avec la méthode V.E.N.T.E. ;', 'gérer les refus et poser dès maintenant des actions à impact immédiat.']::text[], 'Votre offre de lancement rédigée, avec son prix, ses limites et ses bonus, et la liste des premières personnes à qui la présenter.', '[{"question":"Faut-il un site internet ou une page très suivie pour appliquer la méthode ?","reponse":"Non. Le module part du principe que vous démarrez sans site, sans logo et avec peu d’abonnés : il s’appuie sur votre réseau et sur des canaux gratuits."},{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-vendre-sans-site-web-whatsapp-business', 'convertir-les-conversations-en-vente', 5, 'Convertir les conversations en vente', 'entrepreneurs', 'th-ent-vente', 'for-soboro', 'Menez vos conversations commerciales jusqu’à la vente : écouter, proposer, répondre aux objections et relancer sans harceler.', 'Des prospects vous écrivent, mais les échanges s’arrêtent avant l’achat. Vendre trop vite, réciter le même discours ou relancer tous les jours fait fuir. Ce module vous donne des scripts de conversation qui convertissent, une manière d’accueillir les objections comme des signaux d’achat, et un plan de relance en trois étapes.', array['Vous recevez des demandes, mais peu se transforment en ventes.', 'Vous ne savez pas quoi répondre à « c’est cher ».', 'Vous hésitez entre relancer et laisser tomber.']::text[], 'Aucun prérequis particulier. Le module prolonge « Comment construire une offre simple et commencer à vendre ».', array['écouter et reformuler le besoin avant de parler de prix ;', 'mener une conversation de vente avec un script adapté à chaque prospect ;', 'conclure avec des questions fermées ;', 'faire émerger et traiter les objections, dont « c’est cher », sans baisser vos prix ;', 'relancer en trois étapes sans donner le sentiment de harceler.']::text[], 'Vos scripts de conversation, vos réponses aux objections les plus fréquentes et votre plan de relance en trois étapes.', '[{"question":"Les scripts fonctionnent-ils sur WhatsApp et en messagerie ?","reponse":"Oui. Les scripts portent sur la conduite de la conversation : ils s’appliquent aussi bien par message que de vive voix, en les adaptant à chaque prospect."},{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-negocier-et-conclure-une-vente', 'negocier-et-conclure-une-vente', 6, 'Négocier et conclure une vente', 'entrepreneurs', 'th-ent-vente', 'for-cocou', 'Menez un entretien de vente jusqu’à la décision, sans céder systématiquement sur le prix.', 'Beaucoup d’entretiens se terminent par un « je vous rappelle ». Ce module donne une structure d’entretien et les formulations qui permettent de conclure ou d’obtenir un refus clair.', array['Vous vendez vous-même vos prestations.', 'Vos prospects reportent leur décision.', 'Vous acceptez trop souvent de baisser vos prix.']::text[], 'Avoir une offre et un prix définis.', array['conduire un entretien structuré ;', 'répondre aux objections courantes ;', 'obtenir une décision explicite.']::text[], 'Une trame d’entretien annotée et une liste d’objections avec leurs réponses.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-contenus-qui-attirent-des-clients', 'creer-du-contenu-qui-attire-les-clients', 8, 'Créer du contenu qui attire les clients', 'entrepreneurs', 'th-ent-visibilite', 'for-othniel', 'Transformez vos publications en contenus qui suscitent l’intérêt, créent la confiance et génèrent des demandes concrètes.', 'Des vues et des likes ne font pas des clients. Un bon contenu n’attire pas tout le monde : il attire les bonnes personnes, avec le bon message, au bon moment. Ce module vous apprend à connaître votre audience, à bâtir une stratégie de contenu, à écrire des posts qui convertissent et à faire de vos abonnés une communauté engagée.', array['Vous publiez régulièrement, sans clients à la clé.', 'Vous avez des abonnés, mais peu de réactions ou de ventes.', 'Vous dépendez de la publicité pour obtenir des résultats.']::text[], 'Aucun prérequis particulier. Une page professionnelle sur un réseau social permet d’appliquer les exercices.', array['définir votre persona et partir de ce que vit votre client ;', 'alterner les piliers de contenu et raconter l’histoire de votre activité ;', 'structurer un post qui convertit ;', 'planifier vos publications avec un calendrier éditorial ;', 'transformer vos abonnés en communauté engagée ;', 'choisir vos indicateurs selon l’objectif et utiliser la publicité à bon escient.']::text[], 'Votre persona, vos piliers de contenu et un calendrier éditorial prêt à publier.', '[{"question":"Faut-il faire de la publicité pour appliquer le module ?","reponse":"Non. Le module porte d’abord sur le contenu organique. Un chapitre bonus explique quand la publicité devient utile et comment suivre ses résultats."},{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-etre-visible-localement-sur-internet', 'etre-visible-localement-sur-internet', 7, 'Être visible localement sur internet', 'entrepreneurs', 'th-ent-visibilite', 'for-akinocho', 'Apparaissez dans les recherches locales de vos clients, sans budget publicitaire.', 'Une part importante des achats commence par une recherche locale. Ce module met en place les bases : fiche établissement, avis, cohérence des informations et présence sur les plateformes utiles.', array['Vous avez une activité avec une zone de chalandise.', 'Vos clients vous trouvent difficilement en ligne.', 'Vous n’avez pas de budget publicitaire.']::text[], 'Aucun prérequis particulier.', array['créer une fiche établissement complète ;', 'solliciter des avis clients ;', 'maintenir des informations cohérentes.']::text[], 'Une check-list de présence locale complétée pour votre activité.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-mesurer-ce-qui-fait-vraiment-avancer-son-activite', 'mesurer-ce-qui-fait-vraiment-avancer-son-activite', 9, 'Mesurer ce qui fait vraiment avancer son activité', 'entrepreneurs', 'th-ent-visibilite', 'for-akinocho', 'Suivez cinq indicateurs utiles plutôt que vingt tableaux que personne ne lit.', 'Sans mesure, chaque décision se prend au ressenti. Ce module sélectionne les indicateurs qui comptent réellement pour une petite structure et installe une routine de suivi hebdomadaire.', array['Vous ne savez pas quoi mesurer.', 'Vous accumulez des données sans les exploiter.', 'Vous voulez décider sur des faits.']::text[], 'Aucun prérequis particulier.', array['sélectionner ses indicateurs ;', 'construire un tableau de bord simple ;', 'installer une routine de revue.']::text[], 'Un tableau de bord d’une page, complété avec vos propres données.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-transformer-tiktok-en-machine-dacquisition-client', 'transformer-tiktok-en-machine-dacquisition-client', 10, 'Transformer TikTok en machine d’acquisition client', 'entrepreneurs', 'th-ent-visibilite', 'for-soboro', 'Faites de votre compte TikTok une source régulière de clients : des contenus qui vendent, des lives structurés et des statistiques qui guident vos choix.', 'Des vues pour des vues ne servent à rien quand on vend un produit ou un service. Pour que TikTok amène des clients, il faut un objectif, des contenus qui poussent à agir, un moyen simple de vous contacter et de la régularité. Ce module vous montre comment construire votre tunnel de vente TikTok, structurer vos contenus et vos lives, et lire vos statistiques pour améliorer vos résultats.', array['Vous publiez sur TikTok, mais vos vues ne se transforment pas en ventes.', 'Vous voulez utiliser les lives pour vendre.', 'Vous ne savez pas lire les statistiques de vos vidéos.']::text[], 'Avoir un compte TikTok pour votre activité.', array['comprendre et construire votre tunnel de vente TikTok ;', 'bâtir vos contenus à partir de votre cible, en combinant trois types de contenus ;', 'fixer un rythme de publication tenable et organiser votre création ;', 'formuler des appels à l’action et animer un live qui vend ;', 'juger une vidéo sur sa capacité à vendre, notamment par la durée de visionnage.']::text[], 'Votre stratégie de contenu TikTok, avec votre cible, votre calendrier de publication et vos appels à l’action.', '[{"question":"Faut-il déjà avoir beaucoup d’abonnés sur TikTok ?","reponse":"Non. Le module explique comment gagner en visibilité puis transformer les vues en clients, quel que soit le nombre d’abonnés de départ."},{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true),
  ('mod-comprendre-le-business-du-client', 'comprendre-le-business-du-client', 11, 'Comprendre le business du client', 'entrepreneurs', 'th-ent-fondations', 'for-declercq', 'Apprenez à lire une entreprise avant de lui proposer quoi que ce soit : son modèle, son histoire et ce qui la fait vivre.', 'On propose souvent une solution avant d’avoir compris l’activité qu’elle est censée servir. Ce module donne la grille de lecture qui permet de comprendre un modèle économique, ses marges et ses priorités, puis d’en déduire ce dont l’entreprise a réellement besoin.', array['Vous vendez une prestation à des entreprises.', 'Vos recommandations sont difficiles à défendre en réunion.', 'Vous souhaitez relier vos propositions aux objectifs commerciaux du client.']::text[], 'Aucun prérequis particulier.', array['analyser le modèle économique d’une entreprise ;', 'identifier ses priorités commerciales ;', 'formuler une proposition alignée sur ses objectifs.']::text[], 'Une fiche de cadrage client réutilisable pour chaque nouvelle entreprise ou chaque nouveau projet.', '[{"question":"La session de coaching collectif est-elle comprise dans le prix ?","reponse":"Oui. L’achat donne accès aux sessions liées à la thématique du module, selon le calendrier et les places disponibles. Votre fiche apprenant devra être complétée avant votre participation."},{"question":"Puis-je revoir le module après l’avoir terminé ?","reponse":"Oui. Vous conservez un accès à vie au module depuis votre espace apprenant."}]'::jsonb, 60, 10000, 'disponible', '2026-06-01', null, false, '{}'::text[], null, null, null, null, null, null, null, null, null, null, true);
